"""Known, read-only DataLab web requests, with input and response validation."""

import re
import threading
import time
from datetime import date, datetime, timedelta, timezone
from typing import Any

from curl_cffi import requests

__all__ = ["DatalabClient", "UpstreamError"]

BASE_URL = "https://datalab.naver.com/shoppingInsight/"
KST = timezone(timedelta(hours=9))
TIME_UNITS = {"date", "week", "month"}
METRICS = {"clicks": "ClickTrend", "gender": "GenderRate", "age": "AgeRate", "device": "DeviceRate"}


class UpstreamError(RuntimeError):
    """Naver rejected a request or returned an unexpected response."""


def _cid(value: str, *, root: bool = False) -> str:
    value = str(value)
    if not re.fullmatch(r"[0-9]{8}", value) and not (root and value == "0"):
        raise ValueError("cid must be an 8-digit category ID (or 0 for the category root)")
    return value


def _time_unit(value: str) -> str:
    if value not in TIME_UNITS:
        raise ValueError("time_unit must be date, week, or month")
    return value


def _selection(value: str, allowed: set[str], name: str) -> str:
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a comma-separated string")
    if not value:
        return ""
    items = [item.strip() for item in value.split(",")]
    if any(item not in allowed for item in items) or len(set(items)) != len(items):
        raise ValueError(f"{name} must contain unique values from {', '.join(sorted(allowed))}")
    return ",".join(items)


def _period(start_date: str | None, end_date: str | None) -> tuple[str, str]:
    yesterday = datetime.now(KST).date() - timedelta(days=1)
    for value in (start_date, end_date):
        if value is not None and not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", value):
            raise ValueError("dates must use YYYY-MM-DD")
    end = date.fromisoformat(end_date) if end_date is not None else yesterday
    start = date.fromisoformat(start_date) if start_date is not None else end - timedelta(days=29)
    try:
        earliest = end.replace(year=end.year - 1)
    except ValueError:
        earliest = end.replace(year=end.year - 1, day=28)
    if start < date(2017, 8, 1) or not earliest <= start <= end <= yesterday:
        raise ValueError("period must start on/after 2017-08-01, end by yesterday in KST, and span at most one year")
    return start.isoformat(), end.isoformat()


def _filters(
    cid: str,
    start_date: str | None,
    end_date: str | None,
    time_unit: str,
    device: str,
    gender: str,
    ages: str,
) -> dict[str, str]:
    start, end = _period(start_date, end_date)
    return {
        "cid": _cid(cid),
        "startDate": start,
        "endDate": end,
        "timeUnit": _time_unit(time_unit),
        "device": _selection(device, {"pc", "mo"}, "device"),
        "gender": _selection(gender, {"f", "m"}, "gender"),
        "age": _selection(ages, {"10", "20", "30", "40", "50", "60"}, "ages"),
    }


def _check_ranks(card: Any) -> None:
    if not isinstance(card, dict) or "returnCode" not in card:
        raise UpstreamError("Ranking response has no returnCode")
    if card["returnCode"] != 0:
        return  # Preserve explicit failed cards; never convert them into empty successful cards.
    if not isinstance(card.get("ranks"), list):
        raise UpstreamError("Ranking response has no ranks array")
    ranks, keywords = set(), set()
    for item in card["ranks"]:
        if (
            not isinstance(item, dict)
            or type(item.get("rank")) is not int
            or item["rank"] < 1
            or not isinstance(item.get("keyword"), str)
            or not item["keyword"].strip()
        ):
            raise UpstreamError("Invalid ranking item")
        if item["rank"] in ranks or item["keyword"] in keywords:
            raise UpstreamError("Duplicate rank or keyword in a ranking card")
        ranks.add(item["rank"])
        keywords.add(item["keyword"])


class DatalabClient:
    """Read public shopping data without browser login cookies.

    Requests are serialized and spaced per client. No automatic retry or data cache
    is used. Raw response fields remain under ``data`` for traceability.
    """

    def __init__(self, timeout: float = 20, min_interval: float = 0.35) -> None:
        """Set a finite request timeout and minimum request interval in seconds."""
        if timeout <= 0 or min_interval < 0:
            raise ValueError("timeout must be positive and min_interval nonnegative")
        self.timeout = timeout
        self.min_interval = min_interval
        self._lock = threading.Lock()
        self._last_request = 0.0

    def _request(self, method: str, path: str, params: dict[str, Any], *, query: bool = False) -> dict[str, Any]:
        with self._lock:
            time.sleep(max(0, self.min_interval - (time.monotonic() - self._last_request)))
            try:
                response = requests.request(
                    method,
                    BASE_URL + path,
                    params=params if query else None,
                    data=None if query else params,
                    headers={"Referer": BASE_URL + "sCategory.naver", "X-Requested-With": "XMLHttpRequest"},
                    impersonate="safari",
                    timeout=self.timeout,
                    allow_redirects=False,
                )
            except requests.RequestsError as exc:
                raise UpstreamError("Naver request failed or timed out") from exc
            finally:
                self._last_request = time.monotonic()
        if response.status_code != 200:
            raise UpstreamError(f"Naver returned HTTP {response.status_code}; request was not retried")
        try:
            data = response.json()
        except ValueError as exc:
            raise UpstreamError("Naver returned a non-JSON response") from exc
        return {
            "source": response.url,
            "fetched_at": datetime.now(timezone.utc).isoformat(),
            "request": {"method": method, "parameters": params},
            "upstream_content_type": response.headers.get("content-type", ""),
            "data": data,
        }

    def categories(self, cid: str = "0") -> dict[str, Any]:
        """Return a category and its immediate children; root ID is 0."""
        result = self._request("GET", "getCategory.naver", {"cid": _cid(cid, root=True)}, query=True)
        data = result["data"]
        if (
            not isinstance(data, dict)
            or str(data.get("cid")) != str(cid)
            or not isinstance(data.get("childList"), list)
        ):
            raise UpstreamError("Unexpected category response")
        return result

    def ranks(self, cid: str = "50000000", time_unit: str = "date") -> dict[str, Any]:
        """Return recent home ranking cards for one category and time unit."""
        result = self._request(
            "POST", "getKeywordRank.naver", {"cid": _cid(cid), "timeUnit": _time_unit(time_unit)}, query=True
        )
        cards = result["data"]
        if not isinstance(cards, list) or not cards:
            raise UpstreamError("Expected a nonempty array of ranking cards")
        dates = []
        for card in cards:
            _check_ranks(card)
            try:
                dates.append(datetime.strptime(card["date"], "%Y/%m/%d").date())
            except (KeyError, TypeError, ValueError) as exc:
                raise UpstreamError("Ranking card date is missing or invalid") from exc
        if len(set(dates)) != len(dates):
            raise UpstreamError("Duplicate ranking card dates")
        result["partial"] = any(card["returnCode"] != 0 for card in cards)
        result["measurement"] = "keyword_rank_not_search_volume_or_sales"
        return result

    def trends(self, cid: str = "50000000", time_unit: str = "date") -> dict[str, Any]:
        """Compare the latest card with the preceding returned card, without inventing missing ranks."""
        result = self.ranks(cid, time_unit)
        cards = sorted(result["data"], key=lambda card: card["date"])
        latest = cards[-1]
        previous = cards[-2] if len(cards) > 1 else None
        if latest["returnCode"] != 0:
            raise UpstreamError("Latest ranking card failed; stale data was not substituted")
        comparable = previous is not None and previous["returnCode"] == 0
        previous_ranks = {item["keyword"]: item["rank"] for item in previous["ranks"]} if comparable else {}
        items = []
        for item in latest["ranks"]:
            old_rank = previous_ranks.get(item["keyword"])
            items.append(
                {
                    **item,
                    "previous_rank": old_rank,
                    "rank_change": old_rank - item["rank"] if old_rank is not None else None,
                    "comparison": "matched" if old_rank is not None else (
                        "absent_from_previous_list" if comparable else "unavailable"
                    ),
                }
            )
        result["summary"] = {
            "date": latest["date"],
            "range": latest.get("range"),
            "previous_date": previous["date"] if previous else None,
            "previous_range": previous.get("range") if previous else None,
            "comparison_available": comparable,
            "items": items,
            "note": "Positive rank_change means a higher rank. Missing prior ranks are unknown. Current week/month may be incomplete.",
        }
        return result

    def keywords(
        self, cid: str, start_date: str | None = None, end_date: str | None = None,
        time_unit: str = "date", device: str = "", gender: str = "", ages: str = "", page: int = 1,
    ) -> dict[str, Any]:
        """Return one 20-item page of period/filter-specific popular keywords."""
        if type(page) is not int or not 1 <= page <= 25:
            raise ValueError("page must be an integer between 1 and 25 (20 items/page)")
        params = _filters(cid, start_date, end_date, time_unit, device, gender, ages)
        result = self._request("POST", "getCategoryKeywordRank.naver", {**params, "page": page, "count": 20})
        _check_ranks(result["data"])
        if result["data"]["returnCode"] != 0:
            raise UpstreamError("Popular keyword query failed")
        result["measurement"] = "keyword_rank_not_search_volume_or_sales"
        return result

    def series(
        self, cid: str, scope: str = "category", metric: str = "clicks", keyword: str = "",
        start_date: str | None = None, end_date: str | None = None, time_unit: str = "date",
        device: str = "", gender: str = "", ages: str = "",
    ) -> dict[str, Any]:
        """Return click indices or raw demographic/device indices, never absolute sales or percentages."""
        if scope not in {"category", "keyword"} or metric not in METRICS:
            raise ValueError("scope must be category/keyword; metric must be clicks/gender/age/device")
        params = _filters(cid, start_date, end_date, time_unit, device, gender, ages)
        if scope == "keyword":
            words = [word.strip() for word in keyword.split(",")]
            if not 1 <= len(words) <= 5 or any(not word for word in words) or len(set(words)) != len(words):
                raise ValueError("keyword must contain 1 to 5 distinct comma-separated keywords")
            params["keyword"] = ",".join(words)
        elif keyword:
            raise ValueError("keyword is only supported with scope=keyword")
        result = self._request("POST", f"get{scope.title()}{METRICS[metric]}.naver", params)
        data = result["data"]
        if not isinstance(data, dict) or data.get("success") is not True or not isinstance(data.get("result"), list):
            raise UpstreamError("Chart response failed or changed structure")
        field = "value" if metric == "clicks" else "ratio"
        for series in data["result"]:
            if not isinstance(series, dict) or not isinstance(series.get("data"), list):
                raise UpstreamError("Chart series has no data array")
            for point in series["data"]:
                if not isinstance(point, dict) or type(point.get(field)) not in (int, float):
                    raise UpstreamError("Invalid chart data point")
        result["empty"] = not any(series["data"] for series in data["result"])
        result["effective_filters"] = data.get("shoppingParam")
        result["measurement"] = "relative_click_index" if metric == "clicks" else "relative_group_index_not_percentage"
        return result

"""Small local JSON HTTP API. Run with python -m naver_datalab."""

import argparse
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any
from urllib.parse import parse_qs, urlsplit

from naver_datalab.client import DatalabClient, UpstreamError

__all__ = ["create_server", "main"]

FILTERS = {"cid", "start_date", "end_date", "time_unit", "device", "gender", "ages"}
ROUTES = {
    "/v1/categories": ("categories", {"cid"}),
    "/v1/ranks": ("ranks", {"cid", "time_unit"}),
    "/v1/trends": ("trends", {"cid", "time_unit"}),
    "/v1/keywords": ("keywords", FILTERS | {"page"}),
    "/v1/series": ("series", FILTERS | {"scope", "metric", "keyword"}),
}


def create_server(host: str = "127.0.0.1", port: int = 8765, client: DatalabClient | None = None) -> ThreadingHTTPServer:
    """Create an unstarted local server, optionally with an injected client."""
    api_client = client if client is not None else DatalabClient()

    class Handler(BaseHTTPRequestHandler):
        def _json(self, status: int, payload: dict[str, Any]) -> None:
            body = json.dumps(payload, ensure_ascii=False, allow_nan=False).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Cache-Control", "no-store")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_GET(self) -> None:
            parsed = urlsplit(self.path)
            if parsed.path == "/health":
                self._json(200, {"status": "ok", "upstream_checked": False})
                return
            if parsed.path == "/":
                self._json(200, {"service": "naver-datalab-local", "routes": list(ROUTES), "docs": "docs/local-api.md"})
                return
            if parsed.path not in ROUTES:
                self._json(404, {"error": "not_found"})
                return
            method, allowed = ROUTES[parsed.path]
            try:
                query = parse_qs(parsed.query, keep_blank_values=True, max_num_fields=20)
                if set(query) - allowed or any(len(values) != 1 for values in query.values()):
                    raise ValueError("Unknown or repeated query parameter")
                params: dict[str, Any] = {key: values[0] for key, values in query.items()}
                if method in {"keywords", "series"} and "cid" not in params:
                    raise ValueError("cid is required")
                if "page" in params:
                    params["page"] = int(params["page"])
                result = getattr(api_client, method)(**params)
                self._json(200, result)
            except ValueError as exc:
                self._json(400, {"error": "invalid_request", "message": str(exc)})
            except UpstreamError as exc:
                self._json(502, {"error": "upstream_error", "message": str(exc)})

        def do_POST(self) -> None:
            self._json(405, {"error": "method_not_allowed", "message": "Use GET for this local read-only API"})

        def log_message(self, format: str, *args: Any) -> None:
            return  # Do not retain user search queries in an access log.

    return ThreadingHTTPServer((host, port), Handler)


def main() -> None:
    """Run the local API until interrupted."""
    parser = argparse.ArgumentParser(description="Naver DataLab local JSON API")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=8765)
